def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        base = DAILY_SALARY * 0.28
        if hp <= 2 or no_water >= 2:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    pressure_scores = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
        opp_hp = opp.get('hp', 0)
        opp_nw = opp.get('no_water_days', 0)
        opp_budget = opp.get('budget', 0)
        req = opp.get('water_requirement', WATER_REQ)
        salary = opp.get('daily_salary', DAILY_SALARY)
        score = 0.0
        if pbid is not None:
            score += float(pbid)
        score += max(0.0, (3 - opp_hp)) * 8.0
        score += max(0.0, opp_nw) * 10.0
        score += min(25.0, opp_budget / max(1.0, salary) * 6.0)
        score += max(0.0, req - 10) * 1.5
        pressure_scores.append(score)
        if opp_hp <= 3 or opp_nw >= 2:
            desperate_count += 1
        if opp_budget >= salary * 8:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_pressure = max(pressure_scores) if pressure_scores else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water >= 2:
        urgency += 1.0
    elif no_water >= 1:
        urgency += 0.35
    if day >= 8:
        urgency += 0.15

    if urgency >= 1.4:
        bid = max(DAILY_SALARY * 0.92, highest_prev + 4.0, avg_prev + 8.0)
    elif supply_tight:
        if highest_prev >= DAILY_SALARY * 1.5 and hp >= 5 and no_water == 0:
            bid = DAILY_SALARY * 0.26
        elif highest_prev >= DAILY_SALARY * 1.15:
            bid = max(DAILY_SALARY * 0.58, avg_prev * 0.72)
        else:
            bid = max(DAILY_SALARY * 0.62, highest_prev + 2.0, max_pressure * 0.42)
    elif supply_loose:
        if hp >= 5 and no_water == 0:
            bid = DAILY_SALARY * 0.24
        else:
            bid = DAILY_SALARY * 0.42
    else:
        bid = max(DAILY_SALARY * 0.38, avg_prev * 0.6)
        if desperate_count >= 2:
            bid = max(bid, DAILY_SALARY * 0.55)
        if rich_count >= 2 and highest_prev > DAILY_SALARY * 1.1 and hp >= 5 and no_water == 0:
            bid = min(bid, DAILY_SALARY * 0.3)

    if hp >= 6 and no_water == 0 and highest_prev > DAILY_SALARY * 1.7:
        bid = min(bid, DAILY_SALARY * 0.22)

    reserve_target = 0.0
    if day <= 3:
        reserve_target = DAILY_SALARY * 3.0
    elif day <= 6:
        reserve_target = DAILY_SALARY * 2.0
    else:
        reserve_target = DAILY_SALARY * 1.0

    spend_cap = budget
    if hp >= 4 and no_water == 0:
        spend_cap = max(0.0, budget - reserve_target)
        spend_cap = max(spend_cap, DAILY_SALARY * 0.22)

    if urgency >= 1.4:
        spend_cap = budget

    bid = min(bid, spend_cap, budget)
    bid = max(0.0, bid)

    if budget < DAILY_SALARY * 0.35 and (hp <= 3 or no_water >= 1):
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # React to yesterday's likely pressure: use opponents' previous bid if present.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how aggressive the field is.
    field_bid = 0.0
    if prev_bids:
        field_bid = max(prev_bids)

    # Supply tightness: if supply is closer to MIN_SUPPLY, competition is higher.
    # Use a normalized factor in [0,1].
    if MAX_SUPPLY <= MIN_SUPPLY:
        tight_factor = 0.5
    else:
        tight_factor = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
        if tight_factor < 0.0:
            tight_factor = 0.0
        if tight_factor > 1.0:
            tight_factor = 1.0

    # Base bid: moderate to avoid overpaying, but enough to beat typical ~96-101 avg.
    # Scale with my hp/no_water_days.
    if hp <= 2 or no_water_days >= 2:
        urgency = 0.85
    elif hp <= 4 or no_water_days >= 1:
        urgency = 0.65
    else:
        urgency = 0.55

    # If yesterday had very high bids, slightly increase to avoid losing the water.
    # Otherwise keep near base.
    if field_bid >= DAILY_SALARY * 1.1:
        pressure = 0.10
    elif field_bid >= DAILY_SALARY * 0.9:
        pressure = 0.05
    else:
        pressure = 0.0

    # Tight supply increases competition.
    bid_fraction = urgency + pressure + 0.15 * tight_factor
    if bid_fraction < 0.35:
        bid_fraction = 0.35
    if bid_fraction > 0.95:
        bid_fraction = 0.95

    target = DAILY_SALARY * bid_fraction

    # Don't exceed budget.
    if budget <= 0.0:
        return 0.0

    # If supply is extremely low relative to requirement, we must secure water.
    # (Assume total water scales with supply; we just react via higher bid.)
    if supply < float(WATER_REQ):
        target = max(target, DAILY_SALARY * 0.9)

    # If my hp is already high, avoid overbidding above what seems necessary.
    if hp >= 7:
        target = min(target, DAILY_SALARY * (0.65 + 0.15 * tight_factor))

    # Final cap: ensure we can still survive multiple days.
    # Use a conservative cap of 0.7*budget to prevent depletion.
    cap = budget * 0.7
    return float(min(budget, max(0.0, min(target, cap))))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], WATER_REQ * 0.01)

    initial_bid = DAILY_SALARY * 0.7

    if my_status['hp'] <= 2:
        initial_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        initial_bid = DAILY_SALARY * 0.85

    day_progress_factor = day_context['day'] / EPISODE_DAYS
    initial_bid += initial_bid * day_progress_factor * 0.1

    estimated_total_water_needed = WATER_REQ * (num_alive_opponents + 1)

    if day_context['supply'] < estimated_total_water_needed:
        scarcity_ratio = (estimated_total_water_needed - day_context['supply']) / estimated_total_water_needed
        if scarcity_ratio > 0:
            initial_bid += initial_bid * scarcity_ratio * 0.2

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        if max_yesterday_bid > initial_bid * 0.8:
            initial_bid = max(initial_bid, max_yesterday_bid + 1.0)

    final_bid = min(my_status['budget'], initial_bid)

    if final_bid <= 0 and my_status['budget'] > 0:
        final_bid = 1.0
    elif final_bid <= 0:
        final_bid = 0.0

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Extract last bids from previous_trace
    last_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            last_bids.append(trace['bid'])

    # Base bid: moderate to save money
    base_bid = DAILY_SALARY * 0.55

    # Adjust based on health
    if hp <= 2:
        # Desperate for water
        target_bid = DAILY_SALARY * 0.9
    elif hp <= 5:
        target_bid = DAILY_SALARY * 0.7
    else:
        target_bid = base_bid

    # Respond to opponents' previous high bids
    if last_bids:
        max_prev = max(last_bids)
        if max_prev >= DAILY_SALARY * 0.85:
            # If they bid high, avoid if healthy, else outbid slightly
            if hp > 3:
                target_bid = min(target_bid, DAILY_SALARY * 0.4)
            else:
                target_bid = max(target_bid, DAILY_SALARY * 0.8)
        else:
            # Outbid them by small margin if affordable
            target_bid = max(target_bid, max_prev + 1.0)

    # Never bid more than budget
    return min(budget, target_bid)
